use crate::game_globals::MAX_SHADER_REMAPS;

/// Raven `strcpy(dest, src)` into a fixed-size `[c_char; N]` field — copies
/// bytes up to (and including) the NUL or the buffer capacity, whichever is
/// first (Raven's `strcpy` itself has no bound, but every call site here
/// copies a caller string into a `MAX_QPATH`-sized field, so this stays
/// faithful without reproducing the C overrun).
unsafe fn strcpy_buf<const N: usize>(dest: &mut [c_char; N], src: *const c_char) {
    let mut i = 0usize;
    while i < N - 1 {
        let c = *src.add(i);
        dest[i] = c;
        if c == 0 {
            return;
        }
        i += 1;
    }
    dest[N - 1] = 0;
}

/// Raven `AddRemap`. `remapCount`/`remappedShaders` reached via
/// `ctx.world.globals` (backfilled from the `()` placeholder —
/// see `RemappedShaders` in `game_globals.rs`).
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:20-37`
pub fn AddRemap(
    ctx: GameContext<'_>,
    oldShader: *const c_char,
    newShader: *const c_char,
    timeOffset: f32,
) {
    unsafe {
        let world = &mut *ctx.world;
        for i in 0..world.globals.remapCount as usize {
            let existing = world.globals.remappedShaders.0[i].oldShader.as_ptr();
            if Q_stricmp(oldShader, existing) == 0 {
                strcpy_buf(&mut world.globals.remappedShaders.0[i].newShader, newShader);
                world.globals.remappedShaders.0[i].timeOffset = timeOffset;
                return;
            }
        }
        if (world.globals.remapCount as usize) < MAX_SHADER_REMAPS {
            let i = world.globals.remapCount as usize;
            strcpy_buf(&mut world.globals.remappedShaders.0[i].newShader, newShader);
            strcpy_buf(&mut world.globals.remappedShaders.0[i].oldShader, oldShader);
            world.globals.remappedShaders.0[i].timeOffset = timeOffset;
            world.globals.remapCount += 1;
        }
    }
}

/// Raven `BuildShaderStateConfig`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:39-50`
pub fn BuildShaderStateConfig(ctx: GameContext<'_>) -> *const c_char {
    unsafe {
        const MAX_STRING_CHARS: usize = 1024;
        #[allow(non_upper_case_globals)] // Raven `static char buff[...]` spelling
        static mut buff: [c_char; MAX_STRING_CHARS * 4] = [0; MAX_STRING_CHARS * 4];

        // Zero out the buffer at the start
        for i in 0..MAX_STRING_CHARS * 4 {
            buff[i] = 0;
        }

        let world = &*ctx.world;
        for i in 0..world.globals.remapCount as usize {
            let old_shader_str =
                CStr::from_ptr(world.globals.remappedShaders.0[i].oldShader.as_ptr())
                    .to_string_lossy();
            let new_shader_str =
                CStr::from_ptr(world.globals.remappedShaders.0[i].newShader.as_ptr())
                    .to_string_lossy();
            let time_offset = world.globals.remappedShaders.0[i].timeOffset;

            let formatted = format!("{}={}:{:5.2}@", old_shader_str, new_shader_str, time_offset);
            let out_cstr = CString::new(formatted).unwrap_or_else(|_| CString::new("").unwrap());
            Q_strcat(
                (&raw mut buff).cast::<c_char>(),
                (MAX_STRING_CHARS * 4) as c_int,
                out_cstr.as_ptr(),
            );
        }

        (&raw const buff).cast::<c_char>()
    }
}

/// Raven `G_FindConfigstringIndex`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:66-95`
pub fn G_FindConfigstringIndex(
    ctx: GameContext<'_>,
    name: *const c_char,
    start: c_int,
    max: c_int,
    create: qboolean,
) -> c_int {
    unsafe {
        if name.is_null() || *name == 0 {
            return 0;
        }

        const MAX_STRING_CHARS: usize = 1024;
        let mut i = 1;
        let mut s = [0 as c_char; MAX_STRING_CHARS];
        while i < max {
            trap::GetConfigstring(
                ctx.engine,
                GGetConfigstringArgs::new(start + i, s.as_mut_ptr(), MAX_STRING_CHARS as c_int),
            );
            if s[0] == 0 {
                break;
            }
            if Q_strcmp(s.as_ptr(), name) == 0 {
                return i;
            }
            i += 1;
        }

        if create == qfalse {
            return 0;
        }

        if i == max {
            trap::Error(
                ctx.engine,
                GErrorArgs::new(CString::new("G_FindConfigstringIndex: overflow").unwrap()),
            );
        }

        trap::SetConfigstring(
            ctx.engine,
            GSetConfigstringArgs::new(start + i, CStr::from_ptr(name).to_owned()),
        );

        i
    }
}

